/// <summary>
/// DebuC 05.20.23
/// </summary>
/// <param name = "lPerCompany">boolean</param>
/// <returns>Map</returns>
Map getAccountNumPerCompany(boolean lPerCompany = true)
{
    CustTable               custTable;

    Map                     map;
    NDXUmsatzClass          nDX_UmsatzClass;
    container               conCompany;
    int                     i;
    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds;
    CompanyId               company;

    ;
    if (lPerCompany)
    {
        map = new Map(Types::String, Types::String);
    }
    else
    {
        map = new Map(Types::Integer, Types::String);
    }

    if (this.CustParty)
    {
        nDX_UmsatzClass = NDXUmsatzClass::construct();
        conCompany      = nDX_UmsatzClass.parmConCompanies();

        q       = new Query();
        q.allowCrossCompany(true);
        for (i = 1; i <= conlen(conCompany); i++)
        {
            company  = conpeek(conCompany, i);
            q.addCompanyRange(company);
        }
        qbds   = q.addDataSource(tablenum(CustTable));
        qbds.addRange(fieldnum(CustTable, Party)).value(queryValue(this.CustParty));

        qr = new QueryRun(q);

        while (qr.next())
        {
            custTable          = qr.get(tablenum(CustTable));
            if (lPerCompany)
            {
                map.insert(custTable.dataAreaId, custTable.AccountNum);
            }
            else
            {
                map.insert(NDXHelperCommon::CompanyId2NDXCompany(custTable.dataAreaId), custTable.AccountNum);
            }
        }
    }

    return map;
}

/// <summary>
/// DebuC 05.10.23
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_alliance">CustAccount</param>
static void deleteRecords(NDXUmsSignature _umsSignature, CustAccount _alliance)
{
    NDXTmpCustomerAlliance          table;
    ;

    table.skipDataMethods(true);
    table.skipAosValidation(true);
    table.skipDatabaseLog(true);
    table.skipEvents(true);
    table.skipDeleteActions(true);

    if (_alliance)
    {
        delete_from     table
                where       table.UmsSignature == _umsSignature &&
                            table.Alliance     == _alliance;
    }
    else
    {
        delete_from     table
                where       table.UmsSignature == _umsSignature;
    }
}

/// <summary>
/// DebuC 05.10.23
/// </summary>
/// <param name = "_copyTo">NDXUmsSignature</param>
/// <param name = "_copyToOld">NDXUmsSignature</param>
/// <param name = "_sic">boolean</param>
/// <param name = "_copyFromSic">NDXUmsSignature</param>
/// <param name = "_only4Alliance">CustAccount</param>
static void updateRecords(NDXUmsSignature _copyTo,NDXUmsSignature _copyToOld, boolean _sic, NDXUmsSignature _copyFromSic, CustAccount _only4Alliance)
{

    // bestehende Daten sichern
    NDXTmpCustomerAlliance      table;
    Common                      commonCopySic;
    int64                       anzBefore, anzAfter;
    DictTable                   dictTable;

    NDXUmsSignature         l_copyFrom2 = _copyTo;
    NDXUmsSignature         l_copyTo2   = _copyToOld;        
    boolean                 l_lSic      = _sic;

    //--> 1.2: NDX/PAFFH/NDX_TASK1235003370/09.10.2012
    //BP deviation documented
    table.skipDataMethods(true);
    table.skipAosValidation(true);
    table.skipDatabaseLog(true);
    table.skipEvents(true);
    table.skipDeleteActions(true);
    //<-- NDX/PAFFH/NDX_TASK1235003370/09.10.2012

    // Sicherung der CopyFrom-Daten
    if (l_lSic)
    {
        dictTable       = new DictTable(table.TableId);
        commonCopySic   = dictTable.makeRecord();
        ttsbegin;

        // alte Sicherung löschen
        if (_only4Alliance)
        {
            delete_from     table
                where       table.UmsSignature == _copyFromSic &&
                            table.Alliance     == _only4Alliance;
        }
        else
        {
            delete_from     table
                where       table.UmsSignature == _copyFromSic;
        }

        // aktuelle Daten sichern
        if (_only4Alliance)
        {
            while select table
                where    table.UmsSignature    == l_copyFrom2      &&
                            table.Alliance        == _only4Alliance
            {
                buf2Buf(table, commonCopySic);
                commonCopySic.(dictTable.fieldname2id(identifierstr(UmsSignature))) = _copyFromSic;
                commonCopySic.doInsert();
            }
        }
        else
        {
            while select table
                where    table.UmsSignature == l_copyFrom2
            {
                buf2Buf(table, commonCopySic);
                commonCopySic.(dictTable.fieldname2id(identifierstr(UmsSignature))) = _copyFromSic;
                commonCopySic.doInsert();
            }
        }
        ttscommit;
    }

    if (_only4Alliance)
    {
        anzBefore = (select     count(recid)
                        from    NDXTmpCustomerAlliance
                        where   NDXTmpCustomerAlliance.UmsSignature == l_copyTo2 &&
                                NDXTmpCustomerAlliance.Alliance     == _only4Alliance).recid;

        update_recordset        table
            setting             UmsSignature = l_copyTo2
            where               table.UmsSignature == l_copyFrom2 &&
                                table.Alliance     == _only4Alliance;

        anzAfter  = (select     count(recid)
                        from    NDXTmpCustomerAlliance
                        where   NDXTmpCustomerAlliance.UmsSignature == l_copyTo2 &&
                                NDXTmpCustomerAlliance.Alliance     == _only4Alliance).recid;
    }
    else
    {
        anzBefore = (select     count(recid)
                        from    NDXTmpCustomerAlliance
                        where   NDXTmpCustomerAlliance.UmsSignature == l_copyTo2).recid;

        update_recordset        table
            setting             UmsSignature = l_copyTo2
            where               table.UmsSignature == l_copyFrom2;

        anzAfter  = (select     count(recid)
                        from    NDXTmpCustomerAlliance
                        where   NDXTmpCustomerAlliance.UmsSignature == l_copyTo2).recid;
    }
    if (_copyToOld)
    {
        info(strfmt("@NDX:NDXRecordsSavedIn", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), anzAfter - anzBefore, tableId2Name(table.TableId), l_copyTo2));       // [%1] [%2] Records in [%3] unter [%4] gesichert
    }
    else
    {
        info(strfmt("@NDX:NDXRecordsTransferedTo", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), anzAfter - anzBefore, tableId2Name(table.TableId), l_copyTo2));       // [%1] [%2] Records in [%3] unter [%4] übertragen
    }


}

/// <summary>
/// PaffH 05.02.25
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_alliance">NDXAlliance</param>
/// <param name = "_allianceSub">NDXAlliance</param>
/// <param name = "_custAccount">CustAccount</param>
/// <param name = "_company">NDXCompanys</param>
/// <param name = "_allianceParty">RefRecId</param>
/// <param name = "_custParty">RefRecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXTmpCustomerAlliance</returns>
public static NDXTmpCustomerAlliance find(
    NDXUmsSignature _umsSignature
    , NDXAlliance _alliance
    , NDXAlliance _allianceSub
    , CustAccount _custAccount
    , NDXCompanys _company
    , RefRecId _allianceParty
    , RefRecId _custParty
    , boolean _forUpdate = false)
{
    NDXTmpCustomerAlliance nDXTmpCustomerAlliance;
    nDXTmpCustomerAlliance.selectForUpdate(_forUpdate);

    select firstonly nDXTmpCustomerAlliance
        where nDXTmpCustomerAlliance.UmsSignature == _umsSignature
        && nDXTmpCustomerAlliance.Alliance == _alliance
        && nDXTmpCustomerAlliance.AllianceSub == _allianceSub
        && nDXTmpCustomerAlliance.CustAccount == _custAccount
        && nDXTmpCustomerAlliance.Company == _company
        && nDXTmpCustomerAlliance.AllianceParty == _allianceParty
        && nDXTmpCustomerAlliance.CustParty == _custParty;
    return nDXTmpCustomerAlliance;
}

/// <summary>
/// PaffH 05.02.25
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_alliance">NDXAlliance</param>
/// <param name = "_allianceSub">NDXAlliance</param>
/// <param name = "_custAccount">CustAccount</param>
/// <param name = "_company">NDXCompanys</param>
/// <param name = "_allianceParty">RefRecId</param>
/// <param name = "_custParty">RefRecId</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXTmpCustomerAlliance</returns>
/// <returns></returns>
public static NDXTmpCustomerAlliance findOrCreate(
    NDXUmsSignature _umsSignature
    , NDXAlliance _alliance
    , NDXAlliance _allianceSub
    , CustAccount _custAccount
    , NDXCompanys _company
    , RefRecId _allianceParty
    , RefRecId _custParty
    , boolean _doInsert = true)
{
    NDXTmpCustomerAlliance nDXTmpCustomerAlliance = NDXTmpCustomerAlliance::find(
        _umsSignature, _alliance, _allianceSub, _custAccount, _company, _allianceParty, _custParty, true);
    if (!nDXTmpCustomerAlliance)
    {
        nDXTmpCustomerAlliance.UmsSignature = _umsSignature;
        nDXTmpCustomerAlliance.Alliance = _alliance;
        nDXTmpCustomerAlliance.AllianceSub = _allianceSub;
        nDXTmpCustomerAlliance.CustAccount = _custAccount;
        nDXTmpCustomerAlliance.Company = _company;
        nDXTmpCustomerAlliance.AllianceParty = _allianceParty;
        nDXTmpCustomerAlliance.CustParty = _custParty;
        if (_doInsert)
        {
            nDXTmpCustomerAlliance.insert();
        }
    }
    return nDXTmpCustomerAlliance;
}
